"""Build pages, second pass: every page opens on its own header, states the problem first,
and moves through differently built sections on different surfaces. Used by build_services.py."""
from html import escape as e

# the problem, in the owner's words: (headline, paragraph), three signs, heading for how it works, heading for what changes
X = {
 'phone-agent': (('A missed call is usually a missed job.', 'A caller who reaches voicemail often hangs up and tries the next name on the list. You never see the job you lost.'), ['Missed calls on your phone when you come down the ladder', 'Voicemails you return hours later', 'Callers who had already booked someone else'], 'What the caller hears, start to finish.', 'You stay on the job. The call still turns into an estimate.'),
 'website-chat': (('Your site gets questions when nobody is there to answer them.', 'People look at contractors in the evening. If the only way in is a form or a phone number, the easy move is the back button.'), ['Visits in the evening, forms the next day or never', 'The same three questions by phone every week', 'A contact form as the only way in'], 'A question at 10 PM, answered and booked.', 'The visitor leaves with a time, not a number to call tomorrow.'),
 'social-messages': (('Messages are leads too, and they wait the longest.', 'Facebook, Instagram and Google each have their own inbox. Checking all three between jobs means some messages sit until tomorrow, and by then the person has heard back from someone else.'), ['A message you found three days late', 'Replies typed in a truck at lunch', 'No record of who asked what'], 'Three apps, one inbox, one fast reply.', 'Every channel gets the same quick answer.'),
 'lead-vetting': (('Some leads were never going to be jobs.', 'Outside your area, below your minimum, or only collecting prices. You usually find out after the drive.'), ['Estimates you drove to that were never a fit', 'The same screening questions on every call', 'Good leads waiting behind poor ones'], 'Your questions get asked before anyone drives out.', 'Your time goes to the jobs worth quoting.'),
 'after-hours': (('Nights and weekends are when the urgent calls come.', 'An emergency and a quote request sound the same to voicemail. One needs someone tonight. The other needs a time next week. Without a way to tell them apart, you get woken for everything or miss the one that mattered.'), ['Being on call for every call', 'Emergencies you found out about in the morning', 'Weekend quote requests answered on Monday'], 'One night, sorted while you sleep.', 'The right person is woken, and only when it counts.'),
 'reminders': (('A no-show costs you the drive and the slot.', 'People book an estimate, then life happens. Nobody reminds them, they forget or go with someone else, and you find out in their driveway.'), ['Driving to an empty house', 'Calling the day before to confirm, when you remember', 'Reschedules that turn into never'], 'From booked to the knock on the door.', 'The people on your calendar show up.'),
 'dispatch': (('The schedule is right until the first job runs long.', 'Then someone spends the afternoon on the phone moving crews and warning customers. Usually that someone is you.'), ['A whiteboard or a group text running the day', 'Crews crossing town past each other', 'Customers who found out late that you were late'], 'One day, three crews, and a job that runs over.', 'The day adjusts without you making the calls.'),
 'job-updates': (('Customers who don’t know what is happening start calling.', 'Most complaints are not about the work. They are about waiting at home with no idea when anyone will arrive.'), ['“Where are you” calls in the middle of a job', 'Customers taking a day off for a two-hour visit', 'Finished jobs the customer was the last to hear about'], 'What the customer sees, message by message.', 'They know before they have to ask.'),
 'estimates': (('The estimate you send on Friday lost on Tuesday.', 'Measuring is quick. Sitting down to write it up is what takes days, and the customer is collecting other prices the whole time.'), ['Estimates written at night', 'A stack of site visits not yet priced', 'Customers who say they already went with someone'], 'Measurements in, a draft out, you approve.', 'It goes out the same day, while they still care.'),
 'proposals': (('A price in a text message is easy to say no to.', 'When two contractors come in close, people pick the proposal they understood. A one-line number gives them nothing to choose on except the number.'), ['Quotes sent as a text or a photo of a notepad', 'Customers asking what is included', 'No idea whether they opened it'], 'Three options, laid out so the choice is which.', 'The proposal does some of the selling for you.'),
 'invoicing': (('Finished work you haven’t been paid for is a loan you never agreed to.', 'Invoices wait until you have time to send them, and chasing them is awkward enough that it gets put off. The money was earned weeks ago.'), ['Invoices sent at the end of the month', 'Customers you feel awkward nudging', 'Not knowing who owes you right now'], 'Sent the day the job ends, followed up until it is paid.', 'You get paid without being the one who asks.'),
 'bookkeeping': (('You can’t price the next job if you don’t know what the last one made.', 'Receipts live in the truck, supplier bills live in email, and it all gets sorted once a year in a hurry. By then it is too late to learn anything from it.'), ['A glovebox full of receipts', 'Your accountant asking for the same things every year', 'Guessing at what a job really cost'], 'Every receipt read, labelled and put against a job.', 'Costs by job, ready before anyone asks.'),
 'review-replies': (('An unanswered review still says something.', 'People read the replies as closely as the stars. A good review with no reply looks ignored, and a bad one with no reply looks true.'), ['Reviews from months ago with no reply', 'A bad review you heard about from a customer', 'Replying on one site and not the others'], 'Two reviews, handled two ways.', 'Every review is answered, and the hard ones come to you first.'),
 'win-backs': (('Your past customers have lost your number.', 'They liked the work. They would hire you again or pass your name on. But years go by, nobody writes, and the next job goes to whoever shows up in a search.'), ['A customer list that only lives in old invoices', 'Repeat work that comes in by accident', 'Slow months with nobody to call'], 'A year of past customers, each written to at the right time.', 'People who already trust you hear from you again.'),
 'maintenance-reminders': (('Repeat work is due on a date nobody is tracking.', 'Staining, servicing, seasonal checks. The customer does not remember when it is due and neither do you, so somebody else gets asked.'), ['Maintenance work that only comes when the customer remembers', 'No record of what is due when', 'A quiet off-season'], 'The job sets the date. The reminder does the rest.', 'The work comes back round on its own.'),
 'referrals': (('Happy customers would send a neighbor. Almost none are asked.', 'The moment to ask is right after they tell you they are pleased. That moment passes while you are loading the truck.'), ['Referrals that happen by luck', 'No easy way for a customer to pass you on', 'Not knowing which jobs came from whom'], 'One customer, asked once, becomes a street.', 'Asking happens every time, at the right moment.'),
 'campaigns': (('You paid to win these customers once. Most never hear from you again.', 'A slow week is coming and you already have a list of people who know your work. Without someone to write and send the message, the list just sits there.'), ['A slow stretch with no plan to fill it', 'A customer list nobody has written to', 'Paying for new leads while old customers go quiet'], 'One message, sent to the people it fits.', 'Your own list fills the gaps.'),
 'local-search': (('Your Google profile is your shopfront, and it is out of date.', 'It is the first thing a nearby customer sees. Old photos, wrong hours and unanswered questions make a busy business look closed.'), ['The last post was a year ago', 'Questions on the profile with no answer', 'Hours or services that are no longer right'], 'A profile that is updated every week.', 'You look as busy online as you are.'),
 'job-photos': (('Your best marketing is sitting on your crew’s phones.', 'Every finished job is proof you do good work. The photos get taken and never leave the camera roll, because writing a post is nobody’s job.'), ['A camera roll full of finished jobs', 'A feed that goes quiet in busy season', 'Posts only when someone remembers'], 'One photo in, three posts out.', 'Finished work gets seen without anyone writing a caption.'),
 'hiring': (('Good tradespeople take the first decent offer.', 'Applications arrive while you are on a job. By the time you read them and start calling, the good ones have started somewhere else.'), ['Applications read a week late', 'Phone screens that go nowhere', 'Applicants who never heard back'], 'Seven applicants, sorted before you call anyone.', 'You talk to the ones who fit, first.'),
 'team-assistant': (('Every question still comes to you.', 'How do we price this, what is the warranty, which supplier. You are the only one who knows, so your phone rings all day and nothing moves while you are busy.'), ['The same questions from the crew every week', 'New hires who need you beside them', 'Work that stops when you can’t be reached'], 'A question from the job site, answered from your playbook.', 'The crew gets answers without waiting for you.'),
 'field-notes': (('What the crew saw on site is gone by Friday.', 'Nobody wants to type notes at the end of a job. So what was found, what was used and what is still to do stays in someone’s head until it doesn’t.'), ['Job notes that just say “done”', 'Materials remembered at invoice time', 'Return visits nobody scheduled'], 'A minute of talking becomes the job record.', 'The details are on the job before the truck leaves.'),
 'reports': (('You find out how the month went after it is over.', 'The numbers exist, spread across your phone, your calendar and your books. Nobody has time to pull them together, so decisions get made on feel.'), ['Not knowing how many leads came in last week', 'Quotes that went quiet without anyone noticing', 'Surprises at tax time'], 'One page, every Monday.', 'You see the week before it becomes the month.'),
 'call-review': (('Somewhere in last month’s calls is the job you didn’t get.', 'Nobody has hours to listen back. So the same calls keep going wrong the same way, and it never gets fixed.'), ['No idea why callers don’t book', 'Prices asked for and never given', 'Coaching based on the one call you overheard'], 'Every call read, the moment it was lost flagged.', 'You fix the pattern, not just the call.'),
 'custom-agents': (('There is a job in your business that eats hours and never needed you.', 'Checking supplier quotes, chasing permits, updating the job board. It follows the same steps every time, and it still lands on your desk.'), ['A task you could explain to a new hire in ten minutes', 'The same steps, every day', 'Work that waits because you are the one who does it'], 'One task, done your way, inside limits you set.', 'It runs. You check what it did.'),
 'custom-builds': (('Your business has a problem that isn’t on anyone’s list.', 'Off-the-shelf software solves the common ones. The one that costs you most is usually specific to how you work.'), ['A spreadsheet holding something important together', 'A step everyone agrees is a waste of time', 'Software you bend your process around'], 'Your process, described once and built.', 'The tool fits the way you already work.'),
}
# what we need from the owner, and what we take care of, by group
YW = {
 'desk': (['Your hours and service area', 'The questions you ask a new lead', 'Who gets the call when it needs a person'], ['Set it up around the number and pages you already use', 'Test it with you before it takes a real lead', 'Watch the first weeks and adjust']),
 'cal': (['Your working hours and crews', 'How long each kind of job takes', 'How much notice you need'], ['Connect the calendar you already use', 'Write every message in your voice', 'Watch the first weeks and adjust']),
 'sales': (['Your price book or a few recent quotes', 'How you scope a job', 'A final check on everything that goes out'], ['Build your templates', 'Fit it to how you approve a quote', 'Tune it against the quotes you send']),
 'money': (['The payment provider and books you already use', 'Your payment terms', 'Which customers to leave alone'], ['Connect them', 'Write reminders that sound like you', 'Check the first month with you']),
 'after': (['Your customer list, however messy', 'What you want to be known for', 'A yes before anything is sent'], ['Clean the list up', 'Write the messages in your voice', 'Honor every opt-out']),
 'seen': (['Access to your profile and pages', 'Photos from real jobs', 'A yes or no on posts, if you want one'], ['Write and post every week', 'Keep your details correct', 'Answer questions from your own information']),
 'team': (['The documents and habits you already have', 'The questions that come up most', 'Who should see what'], ['Set it up where your crew already talks', 'Keep it to your own information', 'Adjust it as the crew uses it']),
 'custom': (['An hour to walk us through the job', 'Access to the tools it touches', 'The limits it has to stay inside'], ['Scope it in writing', 'Build it and test it with you', 'Watch it run and adjust']),
}
# per page: how it opens, how its section heads are set, and a flip. No two neighbours in the menu share a recipe.
PG = {'phone-agent': ('split', 'a', 0), 'website-chat': ('paper', 'c', 0), 'social-messages': ('story', 'b', 0), 'lead-vetting': ('ledger', 'a', 1), 'after-hours': ('crimson', 'c', 1),
      'reminders': ('week', 'c', 0), 'dispatch': ('numeral', 'b', 1), 'job-updates': ('center', 'a', 0), 'estimates': ('paper', 'b', 1), 'proposals': ('split', 'c', 1),
      'invoicing': ('ledger', 'a', 0), 'bookkeeping': ('week', 'b', 1), 'review-replies': ('story', 'a', 1), 'win-backs': ('numeral', 'c', 0), 'maintenance-reminders': ('week', 'a', 0),
      'referrals': ('center', 'c', 1), 'campaigns': ('crimson', 'b', 0), 'local-search': ('paper', 'a', 0), 'job-photos': ('split', 'b', 1), 'hiring': ('ledger', 'c', 0),
      'team-assistant': ('story', 'c', 0), 'field-notes': ('numeral', 'a', 1), 'reports': ('center', 'c', 0), 'call-review': ('split', 'a', 0), 'custom-agents': ('crimson', 'a', 1), 'custom-builds': ('story', 'b', 1)}
# six ways the rest of the page can run: (module, surface, variant)
FLOWS = [
 [('problem', 'l', 'cards'), ('line',), ('how', 'k', 'strip'), ('changes', 'g', 'cards'), ('setup', 'k', ''), ('questions', 'k', '')],
 [('problem', 'k', 'rows'), ('how', 'g', 'time'), ('line',), ('changes', 'l', 'strike'), ('setup', 'k', ''), ('questions', 'g', '')],
 [('problem', 'c', 'rows'), ('how', 'k', 'list'), ('changes', 'l', 'strike'), ('setup', 'g', ''), ('line',), ('questions', 'k', '')],
 [('problem', 'g', 'cards'), ('how', 'k', 'strip'), ('setup', 'l', ''), ('changes', 'k', 'table'), ('line',), ('questions', 'k', '')],
 [('problem', 'l', 'rows'), ('how', 'g', 'list'), ('line',), ('setup', 'k', ''), ('changes', 'k', 'cards'), ('questions', 'g', '')],
 [('problem', 'k', 'cards'), ('line',), ('how', 'g', 'time'), ('changes', 'l', 'table'), ('setup', 'k', ''), ('questions', 'k', '')],
]
LAB = {'problem': 'The problem', 'how': 'How it works', 'changes': 'What changes', 'setup': 'Getting set up', 'questions': 'Questions'}
WHEN = ('First', 'Then', 'Next', 'Last')
CTA = '<a class="btn" href="https://cal.com/audit-call/15min" target="_blank" rel="noopener" data-cta>Book your free audit</a>'

def compose(p, k, ctx):
    """p: page dict. k: position inside its group. ctx: gname, rel (list of page dicts), ribbon(i), num, total, plate (title, caption), extra html."""
    slug, g = p['slug'], p['group']; (ph, pp), signs, howh, chgh = X[slug]; hero, hs, alt = PG[slug]; mods = FLOWS[ctx['i'] % 6]
    pt, pc = ctx['plate']; rib = ctx['ribbon']; gn = e(ctx['gname'])
    plate = f'<figure class="plate"><header><span>Fig. 1</span><b>{e(pt)}</b><i>Sample data</i></header><div class="st-fig" data-build="{slug}" role="img" aria-label="{e(pt)}. {e(pc)}"></div><figcaption><span>{e(pc)}</span></figcaption></figure>'
    crumb = f'<p class="eb"><a href="/everything">{gn}</a> / {e(p["name"])}</p>'; h1 = f'<h1 id="h1" class="rv">{e(p["h1"])}</h1>'; lede = f'<p class="lede rv d1">{e(p["lede"])}</p>'
    acts = f'<div class="acts rv d2">{CTA}<a class="btn ghost" href="#problem">See the problem it solves</a></div>'
    names = [m[0] for m in mods if m[0] != 'line']
    toc = ''.join(f'<a href="#{n}">{LAB[n]}<span>{i + 1:02d}</span></a>' for i, n in enumerate(names))
    facts = f'<dl class="facts"><div><dt>Part of</dt><dd>{gn}</dd></div><div><dt>Does</dt><dd>{e(", ".join(b for b, _ in p["does"]))}</dd></div><div><dt>Works with</dt><dd>{e(", ".join(r["name"] for r in ctx["rel"][:3]))}</dd></div><div><dt>Starts with</dt><dd>A free audit. We build it only if the audit calls for it.</dd></div></dl>'
    in_hero = hero in ('split', 'week', 'paper', 'center', 'crimson')
    # ---- eight ways to open a page
    if hero == 'split': H = f'<section class="ov ov-hero svc split{" flip" if alt else ""}" aria-labelledby="h1"><div class="wrap"><div>{crumb}{h1}{lede}{acts}</div>{plate}</div></section>'
    elif hero == 'week': H = f'<section class="hh hh-week" aria-labelledby="h1"><div class="wk" aria-hidden="true">{"".join(f"<span>{d}</span>" for d in (("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun") if g in ("cal", "after") else ("Materials", "Fuel", "Tools", "Subs", "Permits", "Disposal", "Other")))}</div><div class="wrap"><div class="hh-top"><div>{crumb}{h1}</div><div>{lede}{acts}</div></div>{plate}</div></section>'
    elif hero == 'paper': H = f'<section class="hh hh-panel paper{" alt" if alt else ""}" aria-labelledby="h1"><div class="panel"><div class="wrap"><div class="hh-top"><div>{crumb}{h1}</div><div>{lede}{acts}</div></div></div></div><div class="wrap dock">{plate}</div></section>'
    elif hero == 'crimson': H = f'<section class="hh hh-panel crimson" aria-labelledby="h1"><div class="panel"><div class="wrap"><div class="hh-top"><div>{crumb}{h1}</div><div>{lede}{acts}</div></div></div></div><div class="wrap dock">{plate}</div></section>'
    elif hero == 'ledger': H = f'<section class="hh hh-ledger" aria-labelledby="h1"><div class="wrap"><div class="hh-top"><div>{crumb}{h1}</div><div>{lede}{acts}</div></div>{facts}</div></section>'
    elif hero == 'story': H = f'<section class="hh hh-story" aria-labelledby="h1"><div class="backdrop" data-flow="wave" data-p="{rib(k * 2 + 40)}"></div><div class="wrap"><div>{crumb}{h1}</div><div>{lede}{acts}<nav class="toc" aria-label="On this page">{toc}</nav></div></div></section>'
    elif hero == 'center': H = f'<section class="ov ov-hero svc" aria-labelledby="h1"><div class="backdrop" data-flow="wave" data-p="{rib(k * 2 + 60)}"></div><div class="wrap">{crumb}{h1}{lede}{acts}</div></section>\n<section class="platesec{" wide" if alt else ""}"><div class="wrap">{plate}</div></section>'
    else: H = f'<section class="hh hh-num" aria-labelledby="h1"><span class="num" aria-hidden="true">{ctx["num"]:02d}</span><div class="wrap">{crumb}{h1}{lede}{acts}<div class="svc-meta"><span>Build {ctx["num"]:02d} of {ctx["total"]}</span><span>{gn}</span><span>Scoped after your audit</span></div></div></section>'
    bar = f'<div class="chap" id="chap"><div class="wrap"><b>{e(p["name"])}</b><nav aria-label="On this page">{"".join(f"<a href=\"#{n}\">{LAB[n]}</a>" for n in names)}</nav></div></div>'
    def sec(name, sf, body, h2, intro, n):
        if hs == 'a': head = f'<div class="sh-a"><p class="lab"><span><i></i>{LAB[name]}</span><span>{n} of {len(names)}</span></p><h2 class="rv">{e(h2)}</h2><p class="intro">{e(intro)}</p></div>'
        elif hs == 'c': head = f'<div class="sh-c"><p class="c-tag"><b>{n:02d}</b> {LAB[name]}</p><h2 class="rv">{e(h2)}</h2><p class="intro">{e(intro)}</p></div>'
        else: head = f'<div class="sh-b"><span class="lab"><i></i>{n}.0 {LAB[name]}</span><h2 class="rv">{e(h2)}</h2><p class="intro">{e(intro)}</p></div>'
        return f'<section class="sec sf-{sf} hs-{hs} m-{name}" id="{name}"><div class="wrap">{head}<div class="sb">{body}</div></div></section>'
    out = [H, bar]; n = 0
    for m in mods:
        if m[0] == 'line': out.append(f'<section class="ov ov-line"><div class="backdrop" data-flow="wave" data-p="{rib(k * 2 + 21 + len(slug))}"></div><div class="wrap"><p class="say rv">{e(p["line"])}</p></div></section>'); continue
        name, sf, var = m; n += 1
        if name == 'problem':
            v = var
            if v == 'cards': body = '<div class="signs sg-cards">' + ''.join(f'<div><span>Sign {i + 1}</span><p>{e(s)}</p></div>' for i, s in enumerate(signs)) + '</div>'
            else: body = '<ol class="signs sg-rows">' + ''.join(f'<li><span>{i + 1}</span><p>{e(s)}</p></li>' for i, s in enumerate(signs)) + '</ol>'
            out.append(sec(name, sf, '<p class="sk">How you know you have it</p>' + body, ph, pp, n))
        elif name == 'how':
            d = p['does']
            if var == 'strip': st = '<div class="steps st-strip">' + ''.join(f'<div><span>Step {i + 1}</span><b>{e(b)}</b><p>{e(t)}</p></div>' for i, (b, t) in enumerate(d)) + '</div>'
            elif var == 'time': st = '<ol class="steps st-time">' + ''.join(f'<li><span>{WHEN[min(i, 3)]}</span><b>{e(b)}</b><p>{e(t)}</p></li>' for i, (b, t) in enumerate(d)) + '</ol>'
            else: st = '<ol class="steps st-list">' + ''.join(f'<li><span>{n}.{i + 1}</span><b>{e(b)}</b><p>{e(t)}</p></li>' for i, (b, t) in enumerate(d)) + '</ol>'
            body = st if in_hero else (f'<div class="how-split">{plate}{st}</div>' if var == 'time' and hs != 'b' else f'<div class="how-stack">{plate}{st}</div>')
            out.append(sec(name, sf, body, howh, 'Here is what it does, in order. The drawing ' + ('at the top of the page' if in_hero else 'here') + ' shows the same thing happening.', n))
            if ctx.get('extra'): out.append(ctx['extra'])
        elif name == 'changes':
            c = p['cmp']
            if var == 'cards': body = '<div class="chg cg-cards"><div><h3>Without it</h3><ul>' + ''.join(f'<li>{e(x)}</li>' for x, _ in c) + '</ul></div><div class="w"><h3>With it</h3><ul>' + ''.join(f'<li>{e(y)}</li>' for _, y in c) + '</ul></div></div>'
            elif var == 'strike': body = '<div class="chg cg-strike">' + ''.join(f'<div><span>{i + 1}</span><p class="x">{e(x)}</p><p>{e(y)}</p></div>' for i, (x, y) in enumerate(c)) + '</div>'
            else: body = '<div class="chg cg-table"><div class="h"><p>Without it</p><p>With it</p></div>' + ''.join(f'<div><p class="x">{e(x)}</p><p>{e(y)}</p></div>' for x, y in c) + '</div>'
            out.append(sec(name, sf, body, chgh, 'Nothing about how you run jobs has to change. This is the difference on an ordinary day.', n))
        elif name == 'setup':
            you, we = YW[g]
            body = '<div class="yw"><div><h3>What we need from you</h3><ul>' + ''.join(f'<li>{e(s)}</li>' for s in you) + '</ul></div><div><h3>What we take care of</h3><ul>' + ''.join(f'<li>{e(s)}</li>' for s in we) + '</ul></div></div><p class="yw-n">It starts with the free audit. If the audit does not call for this build, we will say so.</p>'
            out.append(sec(name, sf, body, 'A short list from you. The rest is on us.', 'We build it around the tools and habits you already have, and you see it working before it touches a real customer.', n))
        else:
            body = '<div class="qa">' + ''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q, a in p['faq']) + '</div><p class="yw-n">More answers on the <a href="/questions">Questions</a> page, or ask on your audit call.</p>'
            out.append(sec(name, sf, body, {'a': 'What owners ask first.', 'b': 'Before you ask.', 'c': 'The questions we get on every audit call.'}[hs], 'The short answers.', n))
    out.append('<section class="rel"><div class="wrap"><h2 class="rv">Often built alongside.</h2><div class="rel-g">' + ''.join(f'<a href="/{r["slug"]}" class="rv"><b>{e(r["name"])}</b><span>{e(r["short"])}</span></a>' for r in ctx['rel']) + '</div></div></section>')
    out.append('''<script>(function(){var c=document.getElementById('chap');if(!c)return;var a=[].slice.call(c.querySelectorAll('nav a')),s=a.map(function(x){return document.getElementById(x.getAttribute('href').slice(1))});function f(){var y=innerHeight*.4,k=-1;s.forEach(function(el,i){if(el&&el.getBoundingClientRect().top<y)k=i});a.forEach(function(x,i){x.classList.toggle('on',i===k)});c.classList.toggle('stuck',c.getBoundingClientRect().top<=65)}addEventListener('scroll',f,{passive:true});f()})();</script>''')
    return '\n'.join(out)
